    68    plan.dnom_mask = plan.map.get_1_mask (HB_TAG ('d','n','o','m'));
    69    plan.has_frac = plan.frac_mask || (plan.numr_mask && plan.dnom_mask);
    70    hb_tag_t kern_tag = HB_DIRECTION_IS_HORIZONTAL (plan.props.direction) ?
    71                        HB_TAG ('k','e','r','n') : HB_TAG ('v','k','r','n');
    72    plan.kern_mask = plan.map.get_mask (kern_tag);
    73
    74    plan.requested_kerning = !!plan.kern_mask;
    75    bool has_gpos_kern = plan.map.get_feature_index (1, kern_tag) != HB_OT_LAYOUT_NO_FEATURE_INDEX;
    76    bool disable_gpos = plan.shaper->gpos_tag &&
    77                        plan.shaper->gpos_tag != plan.map.chosen_script[1];
    78
    79    /*
    80     * Decide who provides glyph classes. GDEF or Unicode.
    81     */
    82
    83    if (!hb_ot_layout_has_glyph_classes (face))
    84      plan.fallback_glyph_classes = true;
    85
    86    /*
    87     * Decide who does substitutions. GSUB, morx, or fallback.
    88     */
    89
    90    plan.apply_morx = _hb_apply_morx (face);
    91
    92    /*
    93     * Decide who does positioning. GPOS, kerx, kern, or fallback.
    94     */
    95
    96    if (hb_options ().aat && hb_aat_layout_has_positioning (face))
    97      plan.apply_kerx = true;
    98    else if (!disable_gpos && hb_ot_layout_has_positioning (face))
    99      plan.apply_gpos = true;
   100    else if (hb_aat_layout_has_positioning (face))
   101      plan.apply_kerx = true;
   102
   103    if (plan.requested_kerning && !plan.apply_kerx && !has_gpos_kern)
   104    {
   105      /* Apparently Apple applies kerx if GPOS kern was not applied. */
   700    HB_BUFFER_DEALLOCATE_VAR (buffer, glyph_index);
